<script setup>
import {pretty} from '../lib/api.js';
defineProps({runs:Array});
const labels={completed:'已完成',failed:'失败',cancelled:'已停止',limit_reached:'达到上限',interrupted:'已中断'};
</script>
<template><div id="timeline"><div v-if="!runs.length" class="empty-state">开始对话后，执行记录将显示在这里。</div><details v-for="run in runs" :key="run.id" class="execution-run" :class="{failed:['failed','limit_reached','interrupted'].includes(run.status)}"><summary><div class="run-summary-heading"><strong class="run-title">第 {{run.index}} 轮</strong><span class="run-state">{{labels[run.status]||(run.status?'已结束':'运行中')}}</span></div><span class="run-description" :title="run.title">{{run.title}}</span><span class="run-summary-stats">模型 {{run.steps}} 次 · 工具 {{run.tools.length}} 次<template v-if="run.status"> · {{(run.elapsed/1000).toFixed(1)}} s</template></span></summary><div class="run-details"><div class="run-tools"><details v-for="call in run.tools" :key="call.id" class="timeline-item" :class="{ok:call.status==='已完成',error:!!call.result?.error}"><summary><code>{{call.name}}</code></summary><div class="timeline-meta">{{[call.subagent?'子 Agent':null,call.status,call.approval,call.elapsed===undefined?null:`${call.elapsed} ms`].filter(Boolean).join(' · ')}}</div><pre v-if="call.arguments!==undefined">{{pretty(call.arguments)}}</pre><pre v-if="call.result!==undefined">{{pretty(call.result)}}</pre></details></div><div class="run-notes"><p v-if="!run.tools.length&&!run.notes.length&&!run.compactions" class="run-note">本轮未调用工具。</p><p v-if="run.compactions" class="run-note">上下文已整理 {{run.compactions}} 次</p><p v-for="(note,index) in run.notes" :key="index" class="run-note">{{note}}</p></div></div></details></div></template>
